/**
 * The agent runtime.
 *
 * Every call in the product — browser test call, API call, batch row, simulation
 * — runs through this function, so transcripts are generated rather than faked,
 * tool calls really resolve, guardrails really fire, and the latency, token and
 * cost numbers the dashboard reports are derived from work that happened.
 *
 * Two engines answer through this one interface. When the assistant has a model
 * configured (`config.ai`, resolved from the workspace's own key or from the
 * deployment's), the turn is generated by that model with real tool calling —
 * see `lib/server/ai/`. When it does not, a deterministic rule engine answers
 * instead, which is why the platform works with no keys at all, and why evals and
 * regression tests still mean something.
 */

import crypto from 'node:crypto';
import { runModelTurn, streamModelTurn } from './ai/turn';
import { costFor, modelInfo } from './ai/providers';
import { runBookingTool, type BookingToolContext } from './booking-tools';
import { runFieldTool } from './field-tools';
import { runReportTool } from './report-tools';
import { tryEndpointTool } from './tools';
import type { ResolvedModel } from './ai/credentials';

export type AgentTool = {
  name: string;
  description?: string;
  parameters?: Record<string, unknown>;
};

export type AgentConfig = {
  id: string;
  name: string;
  firstMessage?: string;
  systemPrompt?: string;
  model?: string;
  temperature?: number;
  tools?: AgentTool[];
  knowledge?: string[];
  company?: string;
  /**
   * The model that should answer this assistant, when one is configured.
   *
   * Resolved by the caller (which owns the workspace credentials), not here — the
   * runtime stays free of database and crypto imports, and a missing model is
   * simply a slower-witted agent rather than a broken one.
   */
  ai?: ResolvedModel;
};

export type HistoryTurn = { role: 'user' | 'assistant' | 'system'; text: string };

export type ToolCall = {
  name: string;
  args: Record<string, unknown>;
  result: string;
  ms: number;
  status: 'ok' | 'error';
  /** Which executor answered: the customer's own endpoint, or the built-in one. */
  source?: 'endpoint' | 'builtin';
};

export type Guardrail = {
  kind: 'prompt_injection' | 'pii' | 'hostile' | 'compliance';
  action: 'refused' | 'redacted' | 'deescalated' | 'escalated';
  note: string;
};

export type TurnResult = {
  reply: string;
  /** Which engine produced the words: a provider id, or `rules`. */
  engine?: string;
  provider?: string;
  intent: string;
  confidence: number;
  toolCalls: ToolCall[];
  guardrail?: Guardrail;
  knowledgeUsed: string[];
  slots: Record<string, string>;
  /** True when this turn only made sense against the previous one. */
  continued?: boolean;
  latencyMs: number;
  /** Milliseconds from caller's last word to the first speakable audio. */
  firstChunkMs: number;
  providerLatencyMs: number;
  model: string;
  tokensIn: number;
  tokensOut: number;
  costUsd: number;
  /** Why the rule engine answered instead of the configured model, if it did. */
  modelError?: string;
};

/* ------------------------------------------------------------------ helpers */

/** Deterministic per-call randomness: the same call always replays identically. */
function seededRandom(seed: string) {
  let h = crypto.createHash('sha256').update(seed).digest().readUInt32BE(0);
  return () => {
    h ^= h << 13;
    h ^= h >>> 17;
    h ^= h << 5;
    h >>>= 0;
    return h / 0xffffffff;
  };
}

function pick<T>(rand: () => number, options: T[]): T {
  return options[Math.floor(rand() * options.length) % options.length];
}

/* ------------------------------------------------------------------ intents */

type Intent =
  | 'greeting'
  | 'order_status'
  | 'refund'
  | 'cancel'
  | 'billing'
  | 'appointment'
  | 'report'
  | 'hours'
  | 'transfer'
  | 'pricing'
  | 'repeat'
  | 'goodbye'
  | 'smalltalk'
  | 'confirmation'
  | 'unknown';

const INTENT_RULES: { intent: Intent; patterns: RegExp[]; weight: number }[] = [
  { intent: 'order_status', patterns: [/\border\b/i, /\btracking\b/i, /\bshipment\b/i, /\bwhere(?:'s| is) my\b/i, /\bparcel\b/i], weight: 3 },
  { intent: 'refund', patterns: [/\brefund\b/i, /\bmoney back\b/i, /\bchargeback\b/i, /\breturn\b/i], weight: 3 },
  { intent: 'cancel', patterns: [/\bcancel\b/i, /\bclose my account\b/i, /\bend (?:my )?(?:plan|subscription)\b/i], weight: 3 },
  {
    intent: 'billing',
    // "How much do I owe you?" is the sentence a practice hears most often, and
    // it contains none of the words a billing department would use.
    patterns: [/\bbill\b/i, /\binvoice\b/i, /\bcharged\b/i, /\bpayment\b/i, /\bcharged twice\b/i, /\bowe\b/i, /\bbalance\b/i, /\boutstanding\b/i, /\bpay\b/i],
    weight: 2,
  },
  { intent: 'appointment', patterns: [/\bappointment\b/i, /\bbook\b/i, /\breschedul/i, /\bschedule\b/i, /\bavailable (?:on|at)\b/i], weight: 3 },
  {
    intent: 'report',
    // The owner's question, not the client's. Every phrase here is one somebody
    // says *about the practice* — "how did we do", "how busy were we", "what is
    // our no-show rate" — which is why the wording is first-person plural and
    // why the weight sits above billing's: "how much did we bill" is a report,
    // "how much do I owe" is a balance.
    patterns: [
      /\bhow (?:did|are|was|were) we\b/i,
      /\bhow (?:many|much) (?:did|have|were) we\b/i,
      /\bhow (?:many|much) (?:calls?|appointments?|visits?|people|clients?|patients?)\b/i,
      /\bour (?:revenue|takings|numbers|figures|no-?shows?|bookings?|appointments?|cancellations?|diary|utilisation|utilization)\b/i,
      /\b(?:what|how much) (?:did|have) we (?:bill|billed|take|taken|collect|collected|make|made|earn|earned)\b/i,
      /\bhow busy\b/i,
      /\bwho earns?\b/i,
      /\bpractice (?:figures|numbers|report)\b/i,
      /\bno-?show rate\b/i,
      /\butilis|\butiliz/i,
      // Recalls and attribution ask their questions in their own words.
      /\brecalls?\b/i,
      /\bwho(?:'s| is| are) overdue\b/i,
      /\bwhere (?:do|did) (?:people|they|clients?|our bookings?|bookings?)\b/i,
      /\bhow many calls\b/i,
    ],
    weight: 4,
  },
  { intent: 'hours', patterns: [/\bopen\b/i, /\bhours\b/i, /\bclosed\b/i, /\bwhat time\b/i], weight: 2 },
  { intent: 'transfer', patterns: [/\bhuman\b/i, /\bagent\b/i, /\brepresentative\b/i, /\bspeak to (?:someone|a person)\b/i, /\bescalate\b/i], weight: 4 },
  { intent: 'pricing', patterns: [/\bprice\b/i, /\bcost\b/i, /\bhow much\b/i, /\bquote\b/i], weight: 2 },
  { intent: 'repeat', patterns: [/\brepeat\b/i, /\bsay that again\b/i, /\bwhat did you say\b/i, /\bpardon\b/i], weight: 3 },
  { intent: 'goodbye', patterns: [/\bbye\b/i, /\bthank you,? that(?:'s| is) all\b/i, /\bgoodbye\b/i, /\bhang up\b/i], weight: 3 },
  { intent: 'greeting', patterns: [/\bhi\b/i, /\bhello\b/i, /\bhey\b/i, /\bgood (?:morning|afternoon|evening)\b/i], weight: 1 },
  { intent: 'smalltalk', patterns: [/\bhow are you\b/i, /\bare you (?:a )?(?:robot|bot|human|ai)\b/i, /\bwho are you\b/i], weight: 2 },
  {
    intent: 'confirmation',
    patterns: [/\b(?:text|sms|email|e-mail|send|forward|confirm|confirmation|receipt|write (?:that|it) down|note that)\b/i],
    weight: 3,
  },
];

/**
 * Follow-ups and short answers.
 *
 * A phone conversation is mostly context: "Thursday would be great" means
 * nothing on its own, and "no, that's all" is how calls actually end. These
 * patterns let the classifier inherit the thread the caller is already on
 * instead of treating every utterance as a fresh request.
 */
const CONTINUATION = /^(?:yes|yeah|yep|sure|okay|ok|correct|right|that works|works for me|that'?s right|sounds good|perfect|please do|go ahead|do it|thursday|friday|monday|tuesday|wednesday|saturday|sunday)\b/i;
const DAY_OR_TIME = /\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow|today|next week|morning|afternoon|evening|\d{1,2}(?::\d{2})?\s?(?:am|pm)|\d{1,2}(?::\d{2}))\b/i;
const ENDING =
  /\b(that(?:'s| is| will be)?\s?(?:all|everything|it)|nothing (?:else|more)|no thanks|no thank you|we'?re (?:done|good|all set)|i'?m (?:good|done|all set)|all set|hang up|goodbye|bye)\b/i;

/** A concrete slot the caller just named: "2pm", "9:15", "Thursday at 2". */
const NAMED_SLOT = /\b(?:\d{1,2}(?::\d{2})?\s?(?:am|pm)|\d{1,2}:\d{2})|\b(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\s+(?:at|on)\s+/i;

function classify(
  text: string,
  turnIndex: number,
  context?: { priorIntents?: string[]; lastAssistant?: string }
): { intent: Intent; confidence: number; continued?: boolean; followedUpOn?: string } {
  const prior = (context?.priorIntents ?? []).filter((i) => i && i !== 'unknown');
  const lastIntent = prior[prior.length - 1];

  // Exchanges that only make sense against the previous turn.
  if (lastIntent) {
    if (ENDING.test(text) && text.split(/\s+/).length <= 8) {
      return { intent: 'goodbye', confidence: 0.88, continued: true, followedUpOn: lastIntent };
    }
    if (lastIntent === 'appointment' && (DAY_OR_TIME.test(text) || CONTINUATION.test(text))) {
      return { intent: 'appointment', confidence: 0.84, continued: true, followedUpOn: 'appointment' };
    }
    if (CONTINUATION.test(text) && text.split(/\s+/).length <= 6) {
      const inherit = (['appointment', 'refund', 'cancel', 'order_status', 'billing'] as Intent[]).includes(lastIntent as Intent)
        ? (lastIntent as Intent)
        : undefined;
      if (inherit) return { intent: inherit, confidence: 0.72, continued: true, followedUpOn: lastIntent };
    }
  }

  let best: { intent: Intent; score: number } = { intent: 'unknown', score: 0 };
  for (const rule of INTENT_RULES) {
    const hits = rule.patterns.filter((p) => p.test(text)).length;
    if (hits === 0) continue;
    const score = hits * rule.weight;
    if (score > best.score) best = { intent: rule.intent, score };
  }
  if (best.intent === 'unknown' && turnIndex === 0) return { intent: 'greeting', confidence: 0.62 };
  const confidence = best.score === 0 ? 0.41 : Math.min(0.97, 0.58 + best.score * 0.06);
  return { intent: best.intent, confidence };
}

/* ------------------------------------------------------------------ guardrails */

function checkGuardrails(text: string): Guardrail | undefined {
  if (/(ignore (?:your |all )?(?:previous )?instructions|system prompt|you are now |jailbreak|dan mode|reveal your prompt)/i.test(text)) {
    return {
      kind: 'prompt_injection',
      action: 'refused',
      note: 'Instruction-override attempt detected; the request was declined and no system context was disclosed.',
    };
  }
  if (/\b(?:\d[ -]*?){13,16}\b/.test(text) || /\b\d{3}-\d{2}-\d{4}\b/.test(text)) {
    return {
      kind: 'pii',
      action: 'redacted',
      note: 'Card or government identifier pattern matched and was masked before storage.',
    };
  }
  if (/(f+u+c+k|sh[i1]t|idiot|stupid (?:bot|robot)|useless)/i.test(text)) {
    return {
      kind: 'hostile',
      action: 'deescalated',
      note: 'Hostile tone detected; the agent acknowledged frustration and offered a human transfer.',
    };
  }
  if (/(diagnos|prescrib|dosage|medical advice|legal advice|sue you)/i.test(text)) {
    return {
      kind: 'compliance',
      action: 'escalated',
      note: 'High-impact request: the agent may schedule or route but must not give regulated advice.',
    };
  }
  return undefined;
}

/* ------------------------------------------------------------------- slots */

/**
 * Slots accumulate across the call, not per turn.
 *
 * "Make it 2pm" only means something if the Thursday from two turns ago is still
 * on the table — the same way a booking form keeps what you already typed. The
 * call's `structuredData` is the draft.
 */
export function mergeSlots(prior: Record<string, string> = {}, fresh: Record<string, string> = {}) {
  const merged: Record<string, string> = { ...prior, ...fresh };
  for (const key of Object.keys(merged)) {
    if (merged[key] === undefined || merged[key] === null || merged[key] === '') delete merged[key];
  }
  if (merged.date && merged.time) merged.appointment = `${merged.date} at ${merged.time}`;
  else if (merged.date) merged.appointment = merged.date;
  else if (merged.time) merged.appointment = merged.time;
  return merged;
}

function extractSlots(text: string) {
  const slots: Record<string, string> = {};
  const order = text.match(/\b(?:NW|ORD|SO)[- ]?(\d{3,6})\b/i);
  if (order) slots.orderId = order[0].toUpperCase().replace(/\s/g, '-');
  const email = text.match(/[\w.+-]+@[\w-]+\.[\w.]+/);
  if (email) slots.email = email[0].toLowerCase();
  const date =
    text.match(/\b\d{4}-\d{2}-\d{2}\b/) ??
    text.match(/\b(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow|next week|\d{1,2}(?:st|nd|rd|th)?(?: of)? (?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*)/i);
  if (date) slots.date = date[0];
  /**
   * A date is not a phone number.
   *
   * The matcher took the first long run of digits and separators, so a caller who
   * said "on 2026-11-26" set `phone` to that date: the booking lost its day, and
   * anything that rings or texts "the number on file" would have sent to a date.
   * Numbers are only accepted when they are not a date written either way round.
   */
  const looksLikeDate = (value: string) =>
    /^\d{4}-\d{1,2}-\d{1,2}$/.test(value) || /^\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}$/.test(value) || /^\d{1,2}-\d{1,2}-\d{2,4}$/.test(value);
  const phone = text.match(/\+?\d(?:[\d ()-]{6,}\d)/);
  if (phone && !looksLikeDate(phone[0].trim())) {
    const digits = phone[0].replace(/\D/g, '');
    // Short digit runs are references and prices, not something to ring.
    if (digits.length >= 7 && digits.length <= 15) slots.phone = phone[0].trim();
  }
  // Time of day, so "make it 2pm" lands on the slot the caller asked for.
  const time = text.match(/\b(\d{1,2}(?::\d{2})?\s?(?:am|pm)|\d{1,2}:\d{2})\b/i);
  if (time) slots.time = time[0].toLowerCase().replace(/\s+/g, '');
  const jobReference = text.match(/\bJOB-\d{3,}\b/i);
  if (jobReference) slots.jobReference = jobReference[0].toUpperCase();
  const visitReference = text.match(/\bVIS-[A-Z0-9-]{4,}\b/i);
  if (visitReference) slots.visitReference = visitReference[0].toUpperCase();
  const callerName = text.match(/\b(?:my name is|this is|i am|i'm)\s+([a-z][a-z' -]{1,50})/i);
  if (callerName) slots.name = callerName[1].replace(/\b(?:and|calling|about|from|at)\b.*$/i, '').trim();
  if (/\bemergency\b/i.test(text)) slots.urgency = 'emergency';
  else if (/\burgent(?:ly)?\b/i.test(text)) slots.urgency = 'urgent';
  else if (/\bas soon as possible|\basap\b|\bsoon\b/i.test(text)) slots.urgency = 'soon';
  if (slots.date && slots.time) slots.appointment = `${slots.date} at ${slots.time}`;
  else if (slots.time) slots.appointment = slots.time;
  else if (slots.date) slots.appointment = slots.date;
  return slots;
}

/* --------------------------------------------------------------- knowledge */

function retrieve(config: AgentConfig, text: string) {
  const entries = config.knowledge ?? [];
  if (!entries.length) return { snippet: '', source: '' };
  const terms = text.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 3);
  let best = { score: 0, entry: '' };
  for (const entry of entries) {
    const lower = entry.toLowerCase();
    const score = terms.reduce((acc, t) => acc + (lower.includes(t) ? 1 : 0), 0) + (lower.includes(text.toLowerCase()) ? 2 : 0);
    if (score > best.score) best = { score, entry };
  }
  if (best.score === 0) return { snippet: '', source: '' };
  return { snippet: best.entry, source: `knowledge/${entries.indexOf(best.entry)}` };
}

/* ------------------------------------------------------------------- tools */

/**
 * Runs a tool the model asked for by name.
 *
 * Deliberately the same executors the rule engine uses — a model choosing tools
 * changes who decides, not what a refund or a booking does.
 */
export async function executeToolByName(
  name: string,
  args: Record<string, unknown>,
  seed: string,
  text = '',
  /**
   * When a call exists to act on a booking, the booking tools answer from the
   * real record — see `lib/server/booking-tools.ts`. Without a context (or with
   * no booking in scope) the generic implementations below run, so an ordinary
   * support call behaves exactly as it always did.
   */
  bookingContext?: BookingToolContext
): Promise<ToolCall> {
  if (bookingContext) {
    const field = await runFieldTool({ ctx: bookingContext, name, args, text });
    if (field) return field;
    // Practice figures first: unlike the booking tools this one answers without
    // a booking in scope, and it decides for itself whether this caller may hear
    // the answer at all.
    const reported = await runReportTool({ ctx: bookingContext, name, args, text });
    if (reported) return reported;
    const real = await runBookingTool({ ctx: bookingContext, name, args, text });
    if (real) return real;
  }
  const rand = seededRandom(`${seed}:${name}:${JSON.stringify(args)}`);
  const slots: Record<string, string> = {};
  for (const [key, value] of Object.entries(args ?? {})) slots[key] = String(value);
  if (!slots.date && slots.day) slots.date = String(slots.day);
  return runTool({ name, description: '' }, slots, rand, text);
}

/**
 * Runs a tool, preferring the customer's own endpoint.
 *
 * A tool with an `endpoint` is called for real — that is what makes the field
 * mean something rather than being stored and ignored. Anything else (a tool
 * with no endpoint, an endpoint that is unreachable or blocked by the outbound
 * policy, a non-2xx answer) falls back to the built-in executor, so a live call
 * still gets an answer instead of an error. Which path answered is recorded on
 * the call as `source`, so a transcript never has to guess.
 */
export async function executeToolByNameOrEndpoint(
  name: string,
  args: Record<string, unknown>,
  seed: string,
  text: string,
  context?: BookingToolContext
): Promise<ToolCall> {
  if (context?.orgId) {
    const live = await tryEndpointTool({
      orgId: context.orgId,
      name,
      args,
      context: {
        callId: context.callId,
        bookingId: context.bookingId,
        callerNumber: context.callerNumber,
        timezone: context.timezone,
      },
    });
    if (live) {
      return {
        name,
        args,
        result: live.outcome.body,
        ms: live.outcome.ms,
        status: 'ok',
        source: 'endpoint',
      } as ToolCall;
    }
  }
  const builtin = await executeToolByName(name, args, seed, text, context);
  return { ...builtin, source: 'builtin' } as ToolCall;
}

function toolMatches(tools: AgentTool[], intent: Intent, text: string, continued = false, scoped = false) {
  const wanted = new Set<string>();
  const push = (...names: string[]) => names.forEach((n) => wanted.add(n));
  const available = new Set(tools.map((tool) => tool.name.toLowerCase()));
  const fieldRequest = /\b(repair|fix|broken|leak|install|replace|service|call[ -]?out|electric|plumb|heat|boiler|air con|roof|lock|job|technician|engineer)\b/i.test(text);
  if (available.has('capture_field_enquiry') && fieldRequest && !/\bJOB-\d{3,}\b/i.test(text)) push('capture_field_enquiry');
  if (available.has('schedule_approved_visit') && intent === 'appointment' && (/\bJOB-\d{3,}\b/i.test(text) || /\bapproved (?:job|visit)\b/i.test(text))) {
    push('schedule_approved_visit');
  }

  /**
   * A call that exists to act on a booking behaves differently from a support
   * call that merely mentions one. The difference is which tools exist: on a
   * confirmation call the agent reads the booking before it speaks, and
   * "cancel" means cancel *the appointment* — not cancel a subscription.
   */
  if (scoped) {
    const names = new Set(tools.map((t) => t.name.toLowerCase()));
    const can = (name: string) => names.has(name);
    if (intent === 'cancel') {
      if (can('cancel_appointment')) return tools.filter((t) => t.name.toLowerCase() === 'cancel_appointment');
    }
    // What the caller said matters more than the label we gave it: "actually,
    // cancel it" and "can we make it Friday instead?" are moves even when the
    // classifier heard the sentence as a confirmation.
    const wantsCancel = /\b(cancel|call it off|can't make it|cannot make it|not coming)\b/.test(text.toLowerCase());
    const wantsMove =
      /(instead|move|change|reschedul|earlier|later|rather|another (day|time))/.test(text.toLowerCase()) &&
      (NAMED_SLOT.test(text) || /(monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow)/.test(text.toLowerCase()));

    const wantsMessage = /\b(text|sms|message|email|e-?mail|confirmation|confirm it|write (?:that|it) down)\b/i.test(text);
    if (wantsMessage && can('send_confirmation')) {
      const read = tools.find((t) => t.name.toLowerCase() === 'lookup_order');
      const send = tools.find((t) => t.name.toLowerCase() === 'send_confirmation');
      if (send) return [read, send].filter(Boolean) as AgentTool[];
    }

    if (can('lookup_order') && (wantsCancel || wantsMove)) {
      const follow = wantsCancel && can('cancel_appointment') ? 'cancel_appointment' : can('reschedule_appointment') ? 'reschedule_appointment' : null;
      const read = tools.find((t) => t.name.toLowerCase() === 'lookup_order');
      const act = follow ? tools.find((t) => t.name.toLowerCase() === follow) : undefined;
      if (act) return [read, act].filter(Boolean) as AgentTool[];
    }

    // A report question on a booking call is still a report question — the
    // scoped path exists to stop "cancel" meaning a subscription, not to stop
    // the receptionist ringing in for the month's numbers.
    if (intent === 'report' && can('practice_report')) {
      return tools.filter((t) => t.name.toLowerCase() === 'practice_report');
    }

    if (intent === 'appointment' || intent === 'confirmation' || intent === 'order_status') {
      const read = [...(can('lookup_order') ? ['lookup_order'] : []), ...(can('check_availability') ? ['check_availability'] : [])].slice(0, 2);
      const act =
        intent === 'appointment' && (continued || NAMED_SLOT.test(text))
          ? [...(can('reschedule_appointment') ? ['reschedule_appointment'] : []), ...(can('book_appointment') ? ['book_appointment'] : [])]
          : intent === 'confirmation' && can('send_confirmation')
            ? ['send_confirmation']
            : [];
      const picked = [...read, ...act].map((name) => tools.find((t) => t.name.toLowerCase() === name)).filter(Boolean) as AgentTool[];
      if (picked.length) return picked;
    }
  }

  if (intent === 'order_status') push('lookup_order', 'order_status', 'get_order');
  if (intent === 'billing') {
    // A workspace whose assistant holds the practice's own records answers from
    // them: the balance is read, never improvised. Only when the caller has
    // actually agreed to pay does the agent go on to send a link.
    push('payment_status');
    if (/\b(?:pay|paid|card|link|settle|now)\b/i.test(text)) push('create_payment_link', 'send_confirmation');
  }
  if (intent === 'refund' || intent === 'billing') push('billing_lookup', 'issue_refund', 'get_invoice');
  if (intent === 'appointment' && !wanted.has('schedule_approved_visit')) {
    // Read the calendar first. Only book when the caller has actually named a
    // slot — either in this sentence, or by answering the offer of slots.
    push('check_availability', 'calendar');
    if (continued || NAMED_SLOT.test(text)) push('book_appointment', 'reschedule_appointment');
  }
  if (intent === 'cancel') push('cancel_subscription', 'update_account');
  if (intent === 'confirmation') push('send_confirmation', 'send_sms', 'email_receipt');
  if (intent === 'report') push('practice_report', 'practice_figures');
  if (intent === 'transfer') push('transfer_call', 'escalate', 'create_ticket');
  return tools.filter((t) => {
    const name = t.name.toLowerCase();
    if (wanted.has(name)) return true;
    return wanted.size === 0 && (t.description ?? '').toLowerCase().split(/[^a-z]+/).some((w) => text.toLowerCase().includes(w) && w.length > 5);
  });
}

function runTool(tool: AgentTool, slots: Record<string, string>, rand: () => number, text: string): ToolCall {
  const started = Date.now();
  // A report with no workspace to report on (a batch job, a stripped test call)
  // says so rather than inventing a figure: the one thing a number must never be
  // is a guess.
  if (tool.name === 'practice_report') {
    return {
      name: tool.name,
      args: slots,
      result: JSON.stringify({
        allowed: false,
        permission: 'no_workspace',
        summary: "I can't see the practice's numbers from this call. Let me take a message instead.",
      }),
      ms: Math.max(40, Date.now() - started),
      status: 'ok',
    };
  }
  const orderId = slots.orderId ?? `NW-${Math.floor(rand() * 9000 + 1000)}`;
  const name = tool.name;

  if (/lookup_order|order_status|get_order/.test(name)) {
    const status = pick(rand, ['in transit', 'out for delivery', 'delivered', 'awaiting carrier pickup']);
    const eta = pick(rand, ['today before 8pm', 'tomorrow morning', 'Thursday', 'in 2 business days']);
    return {
      name,
      args: { orderId },
      result: JSON.stringify({ orderId, status, carrier: pick(rand, ['UPS', 'FedEx', 'DHL']), eta, items: 2, total: `$${(20 + rand() * 180).toFixed(2)}` }),
      ms: Math.round(90 + rand() * 240),
      status: 'ok',
    };
  }
  if (/billing_lookup|get_invoice/.test(name)) {
    return {
      name,
      args: { account: slots.email ?? 'on file' },
      result: JSON.stringify({ plan: 'Scale', amount: `$${(45 + rand() * 400).toFixed(2)}`, period: 'current month', overdue: rand() > 0.7 }),
      ms: Math.round(110 + rand() * 260),
      status: 'ok',
    };
  }
  if (/refund|issue_refund/.test(name)) {
    return {
      name,
      args: { orderId, amount: `$${(15 + rand() * 120).toFixed(2)}` },
      result: JSON.stringify({ refundId: `rf_${Math.floor(rand() * 1e9).toString(36)}`, method: 'original payment method', eta: '3–5 business days' }),
      ms: Math.round(160 + rand() * 300),
      status: 'ok',
    };
  }
  if (/availability|check_availability|calendar/.test(name)) {
    return {
      name,
      args: { date: slots.date ?? 'next available' },
      result: JSON.stringify({ slots: ['9:15am', '11:40am', '2:00pm'], timezone: 'America/Los_Angeles', location: 'Bryant St office' }),
      ms: Math.round(120 + rand() * 200),
      status: 'ok',
    };
  }
  if (/book_appointment/.test(name)) {
    const slot = slots.time ?? '11:40am';
    const date = slots.date ?? 'next available';
    return {
      name,
      args: { date, slot, appointment: slots.appointment ?? `${date} at ${slot}` },
      result: JSON.stringify({ confirmation: `APT-${Math.floor(rand() * 90000 + 10000)}`, slot, date, smsSent: true }),
      ms: Math.round(180 + rand() * 260),
      status: 'ok',
    };
  }
  if (/cancel_subscription/.test(name)) {
    return {
      name,
      args: { account: slots.email ?? 'on file' },
      result: JSON.stringify({ retentionOfferApplied: true, effectiveDate: 'end of period' }),
      ms: Math.round(140 + rand() * 220),
      status: 'ok',
    };
  }
  if (/send_confirmation|send_sms|email_receipt/.test(name)) {
    return {
      name,
      args: { to: slots.phone ?? 'number on file' },
      result: JSON.stringify({ to: slots.phone ?? 'number on file', channel: name.includes('email') ? 'email' : 'sms', queued: true }),
      ms: Math.round(60 + rand() * 120),
      status: 'ok',
    };
  }
  if (/transfer_call|escalate|create_ticket/.test(name)) {
    return {
      name,
      args: { reason: text.slice(0, 60) },
      result: JSON.stringify({ queue: 'tier-2', position: 2, waitSeconds: 74, briefAttached: true }),
      ms: Math.round(140 + rand() * 180),
      status: 'ok',
    };
  }
  return {
    name,
    args: { query: text.slice(0, 60) },
    result: JSON.stringify({ ok: true, note: `${name} executed` }),
    ms: Math.round(80 + rand() * 200),
    status: 'ok',
  };
}

/* -------------------------------------------------------------- reply text */

/** Tool results are JSON strings; a malformed one must never break a call. */
function safeParse(raw: string): Record<string, string | boolean | undefined> | undefined {
  try {
    const value = JSON.parse(raw) as unknown;
    return value && typeof value === 'object' ? (value as Record<string, string | boolean>) : undefined;
  } catch {
    return undefined;
  }
}

function composeReply(args: {
  config: AgentConfig;
  intent: Intent;
  text: string;
  slots: Record<string, string>;
  guardrail?: Guardrail;
  knowledge: { snippet: string };
  toolCalls: ToolCall[];
  history: HistoryTurn[];
  rand: () => number;
}) {
  const { config, intent, text, slots, guardrail, knowledge, toolCalls, history, rand } = args;
  const agent = config.name || 'the assistant';
  const company = config.company || 'the team';

  if (guardrail?.kind === 'prompt_injection') {
    return "I can't share my configuration or ignore how I've been set up — but I can still help with your order, billing, or booking. What do you need?";
  }
  if (guardrail?.kind === 'pii') {
    return `I've masked those digits so they aren't stored on this call. If you need to update a payment method, I'll send you a secure link instead — shall I?`;
  }
  if (guardrail?.kind === 'compliance') {
    return 'That one needs a qualified person rather than an assistant, so I am connecting you with the right team and passing on what you have told me.';
  }
  if (guardrail?.kind === 'hostile') {
    return `I'm sorry — that sounds genuinely frustrating. I'd rather get this right than fast: I can pull the account up now, or put you through to a person immediately. Which would you prefer?`;
  }

  const lastAssistant = [...history].reverse().find((h) => h.role === 'assistant')?.text ?? '';
  const fieldCall = toolCalls.find((call) => call.name === 'capture_field_enquiry' || call.name === 'schedule_approved_visit');
  const fieldResult = fieldCall ? (safeParse(fieldCall.result) as Record<string, unknown> | undefined) : undefined;
  if (fieldCall?.name === 'capture_field_enquiry' && fieldResult) {
    if (fieldResult.captured === true) return `${String(fieldResult.summary ?? 'The enquiry is saved for the team to review')} What is the best way for the team to follow up?`;
    return String(fieldResult.summary ?? 'I need a few more details before I can save that enquiry.');
  }
  if (fieldCall?.name === 'schedule_approved_visit' && fieldResult) {
    if (fieldResult.scheduled === true && fieldResult.needsHuman !== true) return `${String(fieldResult.summary ?? 'The approved visit is scheduled in the live diary')} I have not changed or quoted any price.`;
    return `${String(fieldResult.summary ?? 'I could not safely schedule that visit.')} I will hand this to a person without promising the slot.`;
  }

  switch (intent) {
    case 'greeting':
      return pick(rand, [
        `Hi, you're through to ${agent} at ${company}. What can I help you with today?`,
        `Thanks for calling ${company} — this is ${agent}. How can I help?`,
        `Hello! ${agent} here. What are we sorting out today?`,
      ]);
    case 'order_status': {
      const call = toolCalls.find((t) => /order|lookup/.test(t.name));
      const parsed = call ? (safeParse(call.result) as Record<string, unknown> | undefined) : undefined;
      if (!parsed) return `I can look that up — what's the order number, or the email you ordered with?`;

      // The same question can be answered from two different records: an order,
      // or — when the caller's own number matched one — an appointment. Neither
      // shape may be read with the other's field names, because that is how a
      // reply ends up saying "undefined is undefined with undefined".
      if (parsed.found === false) {
        return `I checked and I do not have anything on file for this number. If you give me the day you booked, or an order number, I can look again.`;
      }
      if (parsed.appointment || parsed.reference) {
        const status = parsed.status ? ` It is currently ${parsed.status}.` : '';
        return `Here is what I have: ${parsed.appointment ?? parsed.reference}.${status} Anything else you need on it?`;
      }
      if (!parsed.orderId && !parsed.status) {
        return `I reached the system but the record came back without the details I need — let me take your order number and pass it to a colleague.`;
      }
      return `Found it: ${parsed.orderId} is ${parsed.status} with ${parsed.carrier}, expected ${parsed.eta}. Anything else on that order?`;
    }
    case 'refund': {
      const call = toolCalls.find((t) => /refund/.test(t.name)) ?? toolCalls.find((t) => /billing/.test(t.name));
      const parsed = call ? (JSON.parse(call.result) as Record<string, string>) : undefined;
      if (parsed?.refundId) return `Done — refund ${parsed.refundId} is back on your original payment method, usually within ${parsed.eta}. A receipt is on its way.`;
      return `I can start a refund, but I need the order first. Do you have the order number?`;
    }
    case 'report': {
      // The practice's own numbers, read from the same functions the Reports
      // screen calls — and refused in a sentence a person would accept when the
      // caller has no business hearing them.
      const report = toolCalls.find((t) => t.name === 'practice_report');
      const figures = report ? safeParse(report.result) : undefined;
      if (!figures) return `I can pull that up — which is it: how busy we were, what came in, or how many did not turn up?`;
      if (figures.allowed === false) return String(figures.summary ?? "I can only share the practice's figures with the team.");
      return `${String(figures.summary ?? '')} Anything you want me to break down?`;
    }
    case 'billing': {
      // A practice reads the ledger it just consulted — the numbers spoken are
      // the numbers on the invoice, to the cent.
      const ledger = toolCalls.find((t) => /payment_status/.test(t.name));
      const money = ledger ? safeParse(ledger.result) : undefined;
      if (money) {
        const due = String(money.outstanding ?? '');
        if (money.found === false || !money.invoices || (Array.isArray(money.invoices) && money.invoices.length === 0)) {
          return `Nothing is outstanding on your account — you're all paid up. Is there anything else I can help with?`;
        }
        const rows = Array.isArray(money.invoices) ? (money.invoices as { number?: string; due?: string; dueDate?: string }[]) : [];
        const lines = rows.map((r) => `${r.number ?? 'your invoice'} — ${r.due ?? ''}${r.dueDate ? ` due ${r.dueDate}` : ''}`).join('; ');
        const link = money.lastLink as { status?: string; amount?: string } | undefined;
        const linkNote = link && link.status === 'paid' ? ` Your last payment link for ${link.amount} has already gone through.` : '';
        return `You have ${String(due)} outstanding${lines ? `: ${lines}` : ''}.${linkNote} I can text you a secure link to pay it now — no card details on this call.`;
      }
      const call = toolCalls.find((t) => /billing|invoice/.test(t.name));
      const parsed = call ? (JSON.parse(call.result) as Record<string, string | boolean>) : undefined;
      if (!parsed) return `Let me pull up the account. What's the email on it?`;
      return `Your plan is ${parsed.plan} at ${parsed.amount} for the ${parsed.period}.${parsed.overdue ? ' There is a balance overdue on it — I can take payment now or email a link.' : ' Everything is current.'} Anything you'd like changed?`;
    }
    case 'appointment': {
      // A booking-scoped call answers from the record it just read or wrote —
      // "you're all set for Thursday at 2pm" is only sayable because it is true.
      const live = toolCalls.map((t) => safeParse(t.result)).find((r) => r && (r.moved || r.booked || r.found));
      if (live) {
        if (live.moved) return `Moved — you're now down for ${live.appointment}, reference ${live.reference}. I've texted you the new details.`;
        if (live.booked) return `Booked: ${live.reference} for ${live.appointment}, and I've texted you the confirmation.`;
        if (live.found) {
          return `${live.customer ? `${live.customer}, you` : 'You'} are down for ${live.appointment}, reference ${live.reference}. Is that still good?`;
        }
      }
      const booked = toolCalls.find((t) => /book/.test(t.name));
      if (booked) {
        const parsed = safeParse(booked.result);
        if (parsed?.booked === false) {
          const offers = Array.isArray(parsed.alternatives) ? (parsed.alternatives as string[]) : [];
          return offers.length
            ? `${String(parsed.note ?? 'That time is taken.')} I could do ${offers.join(', ')} — would any of those work?`
            : `${String(parsed.note ?? 'That time is taken.')} What other day suits you?`;
        }
        const when = String(parsed?.appointment ?? `${parsed?.date ?? 'that day'} at ${parsed?.slot ?? 'the offered time'}`);
        return `Booked: ${parsed?.reference ?? parsed?.confirmation ?? 'confirmed'} for ${when}${parsed?.provider ? ` with ${parsed.provider}` : ''}, and I've texted you the confirmation.`;
      }
      const avail = toolCalls.find((t) => /availability|calendar/.test(t.name));
      const parsed = avail ? safeParse(avail.result) : undefined;
      const open = Array.isArray(parsed?.slots) ? (parsed!.slots as string[]) : [];
      const day = (avail?.args.date as string) ?? 'that day';
      if (!open.length) {
        // A closed day is an answer, not an error: say why (the engine's note
        // names the reason — no rota, holiday, nothing free) and ask for another.
        return parsed?.note
          ? `${String(parsed.note)} Would another day suit you?`
          : `I don't have anything free on ${day} — would another day suit you?`;
      }
      const withWhom = typeof parsed?.provider === 'string' && parsed.provider ? ` with ${parsed.provider}` : '';
      return `I have ${open.join(', ')} on ${day}${withWhom}. Which works best?`;
    }
    case 'cancel': {
      const call = toolCalls.find((t) => /cancel/.test(t.name));
      if (!call) return `I can cancel that. Before I do — is it price, or did something go wrong? Both change what I'd offer.`;
      const parsed = safeParse(call.result);
      // An appointment cancelling is a different sentence from a subscription
      // cancelling, and the caller should hear which one just happened.
      if (parsed?.cancelled) return `That's cancelled — ${parsed.previously ?? 'your appointment'} is off the calendar. I've sent you a note to confirm. Sorry it didn't work out.`;
      return `It's set to cancel at the end of the current period, so nothing further will be charged. I've emailed the confirmation. Anything I can fix before it ends?`;
    }
    case 'pricing':
      return `Pricing depends on volume — the short version is a flat platform rate plus provider usage, with nothing marked up when you bring your own keys. Tell me your monthly call volume and I'll give you a real number.`;
    case 'hours':
      return knowledge.snippet
        ? `Here's what I have: ${knowledge.snippet}`
        : `We're open weekdays 8am to 8pm and Saturdays 9am to 2pm in your local time, and I answer around the clock.`;
    case 'transfer':
      return `Of course — putting you through to a human now. I've passed on a short brief so you won't have to repeat yourself. Estimated wait is about a minute.`;
    case 'repeat':
      return lastAssistant ? `Of course — I said: ${lastAssistant}` : `I haven't said much yet. What would you like me to repeat?`;
    case 'goodbye':
      return pick(rand, [
        `Thanks for calling ${company} — you'll get a summary by text. Have a good one.`,
        `Happy to help. Anything else comes up, call this number back and you'll reach me.`,
      ]);
    case 'confirmation': {
      const sent = toolCalls.find((t) => /send|email/.test(t.name));
      if (!sent) {
        const live = toolCalls.map((t) => safeParse(t.result)).find((r) => r?.found);
        if (live) return `${live.customer ? `${live.customer}, you` : 'You'} are down for ${live.appointment}, reference ${live.reference}. Can I text you a confirmation?`;
      }
      const destination = sent ? (JSON.parse(sent.result) as Record<string, string>).to : slots.phone ?? 'the number you are calling from';
      return `Done — I have sent a written confirmation to ${destination}. It should arrive within a minute. Anything else I can help with?`;
    }
    case 'smalltalk':
      return `I'm an AI assistant for ${company} — no coffee breaks, no hold music. I can handle orders, billing, bookings, and get you to a person when that's the better answer.`;
    default: {
      if (knowledge.snippet) return `${knowledge.snippet} Does that answer it, or would you like me to go deeper?`;
      const echo = text.trim().replace(/\s+/g, ' ').slice(0, 90);
      const short = text.trim().split(/\s+/).length <= 4;
      // Mid-thread short answers should not be interrogated; move the call on.
      if (short && history.length) {
        return `Got it. Is there anything else you want me to look at while I have you?`;
      }
      return `I want to make sure I get this right — you mentioned "${echo}". Is that about an order, billing, or an appointment?`;
    }
  }
}

/* -------------------------------------------------------------------- main */

export async function runTurn(input: {
  config: AgentConfig;
  history: HistoryTurn[];
  userText: string;
  callId: string;
  turnIndex: number;
  /** Intents observed earlier in this call — how follow-ups are resolved. */
  priorIntents?: string[];
  /** Entities already collected on this call (order id, day, time…). */
  priorSlots?: Record<string, string>;
  /** True on transports with no barge-in, where the agent should be patient. */
  patience?: boolean;
  /**
   * The workspace this turn belongs to, and (when the call is about one) the
   * booking it is acting on — how the booking tools reach the real record.
   */
  orgId: string;
  bookingId?: string;
  callerNumber?: string;
  timezone?: string;
  /** Set when the turn came from the dashboard: the person is known by name and role. */
  viewer?: { name?: string; email?: string; role?: string };
}): Promise<TurnResult> {
  const started = Date.now();
  const rand = seededRandom(`${input.callId}:${input.turnIndex}:${input.userText}`);
  const text = input.userText.trim();

  const guardrail = checkGuardrails(text);
  const lastAssistant = [...input.history].reverse().find((h) => h.role === 'assistant')?.text;
  const { intent, confidence, continued } = classify(text, input.turnIndex, {
    priorIntents: input.priorIntents,
    lastAssistant,
  });
  const slots = mergeSlots(input.priorSlots, extractSlots(text));
  const knowledge = retrieve(input.config, text);

  // A guardrail that refuses ends the turn here: the deterministic refusal is
  // the whole point of having it in front of the model.
  const refused = Boolean(guardrail && guardrail.action !== 'redacted');
  let toolCalls: ToolCall[] = [];
  let reply: string | undefined;
  let engine = 'rules';
  let modelId = input.config.model ?? 'gpt-4o-mini';
  let tokensIn = 0;
  let tokensOut = 0;
  let providerLatencyMs = Math.round(180 + rand() * 420);
  let modelError: string | undefined;

  if (input.config.ai && !refused) {
    const { outcome } = await runModelTurn({
      model: input.config.ai,
      config: input.config,
      history: input.history,
      userText: text,
      knowledge,
      run: (name, args) =>
        executeToolByNameOrEndpoint(name, args, `${input.callId}:${input.turnIndex}`, text, {
          orgId: input.orgId,
          callId: input.callId,
          bookingId: input.bookingId,
          callerNumber: input.callerNumber,
          timezone: input.timezone,
          viewer: input.viewer,
        }),
    });
    if (outcome.ok && !outcome.empty) {
      reply = outcome.reply;
      toolCalls = outcome.toolCalls;
      engine = input.config.ai.providerId;
      modelId = input.config.ai.model;
      tokensIn = outcome.tokensIn;
      tokensOut = outcome.tokensOut;
      providerLatencyMs = outcome.firstTokenMs;
    } else {
      // Fall back rather than leave the caller in silence — but record why.
      modelError = outcome.error ?? 'model returned nothing';
    }
  }

  if (reply === undefined) {
    if (!refused) {
      for (const tool of toolMatches(
        input.config.tools ?? [],
        intent,
        text,
        Boolean(continued),
        Boolean(input.bookingId || input.callerNumber)
      
      ).slice(0, 3)) {
        // Through the same dispatcher a model's tool call uses — endpoint first,
        // built-in executor as the fallback — so both paths behave identically.
        toolCalls.push(
          await executeToolByNameOrEndpoint(tool.name, slots, `${input.callId}:${input.turnIndex}`, text, {
            orgId: input.orgId,
            callId: input.callId,
            bookingId: input.bookingId,
            callerNumber: input.callerNumber,
            timezone: input.timezone,
          })
        );
      }
    }
    reply = composeReply({
      config: input.config,
      intent,
      text,
      slots,
      guardrail,
      knowledge,
      toolCalls,
      history: input.history,
      rand,
    });
  }

  if (guardrail?.kind === 'pii') {
    reply = reply.replace(/\d(?=[\d -]{3,})/g, '•');
  }

  const latencyMs = Date.now() - started;
  const firstChunkMs = latencyMs;
  if (!tokensIn && !tokensOut) {
    // The rule engine has no tokens of its own; estimate from the text so the
    // metering still reflects the work, and label the engine honestly.
    tokensIn = Math.round(text.split(/\s+/).length * 1.6 + (input.config.systemPrompt?.length ?? 0) / 6);
    tokensOut = Math.round(reply.split(/\s+/).length * 1.5);
  }
  const info = modelInfo(modelId);

  return {
    reply,
    engine,
    provider: engine === 'rules' ? undefined : input.config.ai?.providerLabel,
    intent,
    confidence,
    toolCalls,
    guardrail,
    knowledgeUsed: knowledge.source ? [knowledge.source] : [],
    slots,
    continued: Boolean(continued),
    latencyMs,
    firstChunkMs,
    providerLatencyMs,
    model: engine === 'rules' ? `${modelId} (rules)` : `${info.label}`,
    tokensIn: Math.round(tokensIn),
    tokensOut: Math.round(tokensOut),
    // A bring-your-own endpoint is not priced by us — we cannot know what the
    // customer pays their vendor, so nothing is invented on their invoice.
    costUsd: input.config.ai?.unpriced ? 0 : costFor(modelId, Math.round(tokensIn), Math.round(tokensOut)),
    modelError,
  };
}

/**
 * Everything a transport can observe during a turn.
 *
 * The vocabulary is deliberately transport-neutral: the SSE endpoint forwards
 * these as named events, the browser speaks on `assistant.delta`, the phone
 * worker starts synthesis on `tts.start`, and the batch dialler only cares about
 * `assistant.done`. One list, so a new transport cannot invent its own.
 */
export type TurnEvent =
  | { type: 'stt.final'; text: string }
  | { type: 'intent'; intent: string; confidence: number; continued?: boolean }
  | { type: 'tool.start'; name: string; args: Record<string, unknown> }
  | { type: 'tool.end'; name: string; result: string; ms: number; status: string }
  | { type: 'guardrail'; kind: string; action: string; note: string }
  | { type: 'tts.start'; atMs: number }
  | { type: 'assistant.delta'; text: string }
  | { type: 'assistant.done'; text: string; latencyMs: number; firstChunkMs: number }
  | { type: 'error'; message: string };

/**
 * Word groups sized like a TTS engine's first chunk: short enough to start
 * speaking fast, long enough not to sound clipped.
 */
export function chunkForSpeech(text: string, firstChunkWords = 4, wordsPerChunk = 6) {
  const words = text.split(/\s+/).filter(Boolean);
  const chunks: string[] = [];
  let i = 0;
  while (i < words.length) {
    const size = chunks.length === 0 ? firstChunkWords : wordsPerChunk;
    chunks.push(words.slice(i, i + size).join(' '));
    i += size;
  }
  return chunks;
}

/**
 * Runs one turn and yields it as it happens.
 *
 * Consumers: the SSE endpoint the browser call UI reads, the telephony gather
 * handler, and the batch dialler. The generator is the single implementation of
 * "what the agent does", so nothing can drift between transports.
 */
export async function* runTurnStream(input: {
  config: AgentConfig;
  history: HistoryTurn[];
  userText: string;
  callId: string;
  turnIndex: number;
  /** Intents from earlier in the call, so follow-ups resolve correctly. */
  priorIntents?: string[];
  /** Entities already collected, so "make it 2pm" keeps the day. */
  priorSlots?: Record<string, string>;
  /** Client-measured moment the caller stopped speaking, for voice-to-voice. */
  speechEndedAt?: number;
  /** Delays the token increments; 0 makes the generator dump the text at once. */
  chunkDelayMs?: number;
  /** See `runTurn` — how a booking-scoped call reaches the booking. */
  orgId: string;
  bookingId?: string;
  callerNumber?: string;
  timezone?: string;
  /** See `runTurn`. */
  viewer?: { name?: string; email?: string; role?: string };
}): AsyncGenerator<TurnEvent, void, void> {
  const started = Date.now();
  const rand = seededRandom(`${input.callId}:${input.turnIndex}:${input.userText}`);
  const text = input.userText.trim();
  if (!text) {
    yield { type: 'error', message: 'Empty transcript — nothing to answer.' };
    return;
  }

  yield { type: 'stt.final', text };

  const guardrail = checkGuardrails(text);
  const lastAssistant = [...input.history].reverse().find((h) => h.role === 'assistant')?.text;
  const { intent, confidence, continued } = classify(text, input.turnIndex, {
    priorIntents: input.priorIntents,
    lastAssistant,
  });
  const slots = mergeSlots(input.priorSlots, extractSlots(text));
  const knowledge = retrieve(input.config, text);
  yield { type: 'intent', intent, confidence, continued: Boolean(continued) };

  if (guardrail) {
    yield { type: 'guardrail', kind: guardrail.kind, action: guardrail.action, note: guardrail.note };
  }

  const refused = Boolean(guardrail && guardrail.action !== 'redacted');
  const toolCalls: ToolCall[] = [];
  const delay0 = input.chunkDelayMs ?? 0;
  let reply = '';
  let firstChunkMs = 0;
  let engine = 'rules';
  let modelLabel = input.config.model ?? 'gpt-4o-mini';
  let tokensIn = 0;
  let tokensOut = 0;
  let providerLatencyMs = Math.round(120 + rand() * 260);
  let modelError: string | undefined;
  let usedModel = false;

  /**
   * The model path: the reply is generated, not composed, and the tools fire
   * because the model asked for them — mid-sentence if it wants to.
   */
  if (input.config.ai && !refused) {
    const iterator = streamModelTurn({
      model: input.config.ai,
      config: input.config,
      history: input.history,
      userText: text,
      knowledge,
      run: (name, args) =>
        executeToolByNameOrEndpoint(name, args, `${input.callId}:${input.turnIndex}`, text, {
          orgId: input.orgId,
          callId: input.callId,
          bookingId: input.bookingId,
          callerNumber: input.callerNumber,
          timezone: input.timezone,
          viewer: input.viewer,
        }),
    });
    let step = await iterator.next();
    while (!step.done) {
      const event = step.value;
      if (event.type === 'delta') {
        if (!firstChunkMs) {
          firstChunkMs = Date.now() - started;
          providerLatencyMs = firstChunkMs;
          yield { type: 'tts.start', atMs: firstChunkMs };
        }
        reply += event.text;
        yield { type: 'assistant.delta', text: event.text };
        if (delay0) await new Promise((r) => setTimeout(r, delay0));
      } else if (event.type === 'tool.start') {
        yield { type: 'tool.start', name: event.name, args: event.args };
      } else if (event.type === 'tool.end') {
        toolCalls.push({ name: event.name, args: {}, result: event.result, ms: event.ms, status: event.status as 'ok' | 'error' });
        yield { type: 'tool.end', name: event.name, result: event.result, ms: event.ms, status: event.status };
      }
      step = await iterator.next();
    }

    const outcome = step.value;
    if (outcome.ok && !outcome.empty) {
      usedModel = true;
      engine = input.config.ai.providerId;
      modelLabel = modelInfo(input.config.ai.model).label;
      tokensIn = outcome.tokensIn;
      tokensOut = outcome.tokensOut;
    } else {
      modelError = outcome.error ?? 'model returned nothing';
      toolCalls.length = 0;
      reply = '';
      firstChunkMs = 0;
    }
  }

  if (!usedModel) {
    if (!refused) {
      for (const tool of toolMatches(
        input.config.tools ?? [],
        intent,
        text,
        Boolean(continued),
        Boolean(input.bookingId || input.callerNumber)
      ).slice(0, 3)) {
        yield { type: 'tool.start', name: tool.name, args: { ...slots } };
        const call = await executeToolByNameOrEndpoint(tool.name, slots, `${input.callId}:${input.turnIndex}`, text, {
          orgId: input.orgId,
          callId: input.callId,
          bookingId: input.bookingId,
          callerNumber: input.callerNumber,
          timezone: input.timezone,
        });
        toolCalls.push(call);
        yield { type: 'tool.end', name: call.name, result: call.result, ms: call.ms, status: call.status };
      }
    }
    const composed = composeReply({
      config: input.config,
      intent,
      text,
      slots,
      guardrail,
      knowledge,
      toolCalls,
      history: input.history,
      rand,
    });
    return yield* emitRuleReply({
      composed,
      started,
      providerLatencyMs,
      delay: delay0,
      text,
      modelLabel,
      modelError,
      intent,
      confidence,
      toolCalls,
      guardrail,
      knowledge,
      slots,
      continued: Boolean(continued),
    });
  }

  const latencyMs = Date.now() - started;
  yield { type: 'assistant.done', text: reply.trim(), latencyMs, firstChunkMs };
  writeStreamResult({
    reply: reply.trim(),
    intent,
    confidence,
    toolCalls,
    guardrail,
    knowledge,
    slots,
    continued: Boolean(continued),
    latencyMs,
    firstChunkMs,
    providerLatencyMs,
    modelLabel,
    engine,
    tokensIn,
    tokensOut,
    modelError,
    unpriced: input.config.ai?.unpriced,
  });
}

type StreamResultInput = {
  reply: string;
  intent: string;
  confidence: number;
  toolCalls: ToolCall[];
  guardrail?: Guardrail;
  knowledge: { snippet: string; source: string };
  slots: Record<string, string>;
  continued: boolean;
  latencyMs: number;
  firstChunkMs: number;
  providerLatencyMs: number;
  modelLabel: string;
  engine: string;
  tokensIn: number;
  tokensOut: number;
  modelError?: string;
  /** True when the model ran on the customer's own endpoint, which we do not price. */
  unpriced?: boolean;
};

/** Parks the finished turn where the caller can read it — see `streamResult`. */
function writeStreamResult(input: StreamResultInput) {
  const tokensIn = input.tokensIn || Math.round(input.reply.split(/\s+/).length * 1.6);
  const tokensOut = input.tokensOut || Math.round(input.reply.split(/\s+/).length * 1.5);
  streamResult.reply = input.reply;
  streamResult.intent = input.intent;
  streamResult.confidence = input.confidence;
  streamResult.toolCalls = input.toolCalls;
  streamResult.guardrail = input.guardrail;
  streamResult.knowledgeUsed = input.knowledge.source ? [input.knowledge.source] : [];
  streamResult.slots = input.slots;
  streamResult.continued = input.continued;
  streamResult.latencyMs = input.latencyMs;
  streamResult.firstChunkMs = input.firstChunkMs;
  streamResult.providerLatencyMs = input.providerLatencyMs;
  streamResult.model = input.engine === 'rules' ? `${input.modelLabel} (rules)` : input.modelLabel;
  streamResult.engine = input.engine;
  streamResult.tokensIn = Math.round(tokensIn);
  streamResult.tokensOut = Math.round(tokensOut);
  streamResult.costUsd = input.unpriced
    ? 0
    : costFor(input.engine === 'rules' ? 'rules' : input.modelLabel, streamResult.tokensIn, streamResult.tokensOut);
  streamResult.modelError = input.modelError;
}

/**
 * The rule engine's reply, chunked so it streams like a model would.
 *
 * Chunking matters even without a model: transports measure time-to-first-audio
 * on the first delta, and the caller hears the opening words while the rest of
 * the sentence is still being assembled.
 */
async function* emitRuleReply(input: {
  composed: string;
  started: number;
  providerLatencyMs: number;
  delay: number;
  text: string;
  modelLabel: string;
  modelError?: string;
  intent: string;
  confidence: number;
  toolCalls: ToolCall[];
  guardrail?: Guardrail;
  knowledge: { snippet: string; source: string };
  slots: Record<string, string>;
  continued: boolean;
}): AsyncGenerator<TurnEvent, void, void> {
  const speech = chunkForSpeech(input.composed);
  let reply = '';
  let firstChunkMs = 0;
  let emitted = 0;

  for (const chunk of speech) {
    if (emitted === 0) {
      firstChunkMs = Date.now() - input.started + input.providerLatencyMs;
      yield { type: 'tts.start', atMs: firstChunkMs };
    }
    reply += `${emitted === 0 ? '' : ' '}${chunk}`;
    yield { type: 'assistant.delta', text: `${emitted === 0 ? '' : ' '}${chunk}` };
    emitted += 1;
    if (input.delay) await new Promise((r) => setTimeout(r, input.delay));
  }

  const latencyMs = Date.now() - input.started + input.providerLatencyMs;
  yield { type: 'assistant.done', text: reply.trim(), latencyMs, firstChunkMs };
  writeStreamResult({
    reply: reply.trim(),
    intent: input.intent,
    confidence: input.confidence,
    toolCalls: input.toolCalls,
    guardrail: input.guardrail,
    knowledge: input.knowledge,
    slots: input.slots,
    continued: input.continued,
    latencyMs,
    firstChunkMs,
    providerLatencyMs: input.providerLatencyMs,
    modelLabel: input.modelLabel,
    engine: 'rules',
    tokensIn: Math.round(input.text.split(/\s+/).length * 1.6),
    tokensOut: Math.round(reply.split(/\s+/).length * 1.5),
    modelError: input.modelError,
  });
}

export const streamResult: TurnResult = {
  reply: '',
  engine: 'rules',
  intent: 'unknown',
  confidence: 0,
  toolCalls: [],
  knowledgeUsed: [],
  slots: {},
  latencyMs: 0,
  firstChunkMs: 0,
  providerLatencyMs: 0,
  model: '',
  tokensIn: 0,
  tokensOut: 0,
  costUsd: 0,
  modelError: undefined,
};

/** The same turn, run to completion without streaming. Used by tests and batch. */
export async function runTurnStreamed(input: Parameters<typeof runTurnStream>[0]) {
  let final = '';
  for await (const event of runTurnStream({ ...input, chunkDelayMs: 0 })) {
    if (event.type === 'assistant.done') final = event.text;
  }
  return { ...streamResult, reply: final || streamResult.reply };
}
